const D = { density: .55, energy: .6, speed: 1, rows: 11, scale: 1, hue: 30, x: .5, y: .5, style: 'neon', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
const wrap = h => ((h % 360) + 360) % 360;

// --- real-time dt (guard t0 resets / big jumps) ---
if (S.lastT == null || K.t < S.lastT) S.lastT = K.t - 1/60;
let dt = K.t - S.lastT; S.lastT = K.t;
if (!(dt > 0) || dt > 0.4) dt = 1/60;

// --- layout ---
const W = width, H = height, u = Math.min(W, H);
const R = Math.max(5, Math.min(18, Math.round(P.rows)));
const NB = R + 1;
const cx = P.x * W;
const boardW = Math.min(W * 0.94, u * 1.75) * (0.55 + P.scale * 0.5);
const binW = boardW / NB;
const yc = (P.y - 0.5) * H * 0.26;
const yTop = H * 0.10 + yc;
const yPegBot = H * 0.60 + yc;
const yBot = H * 0.965 + yc;
const rowH = (yPegBot - yTop) / R;
const hueSpread = 66;
const capCount = 90;
const aMul = Math.max(0, Math.min(1, P.alpha / 100));

// --- seed / structure init & rebuild ---
if (S.seedUsed !== P.seed || !S.bins || S.nb !== NB) {
  S.seedUsed = P.seed; S.balls = []; S.bins = new Float32Array(NB);
  S.nextId = 0; S.nb = NB; S.emitAcc = 0; S.drain = false;
}

// --- style palette ---
const sec = (K.section | 0);
const secHue = sec * 13;
const style = P.style;
let wire = false, mono = false, thermal = false;
let bgT, bgB, pegC, sat, hueBase;
if (style === 'gold') {
  mono = true; sat = 88; hueBase = 44; bgT = [42,60,5]; bgB = [38,55,14]; pegC = [45,70,24];
} else if (style === 'thermal') {
  thermal = true; sat = 90; hueBase = 40; bgT = [222,72,7]; bgB = [248,52,17]; pegC = [210,45,28];
} else if (style === 'phosphor') {
  mono = true; sat = 92; hueBase = 132; bgT = [135,82,5]; bgB = [140,70,14]; pegC = [135,85,22];
} else if (style === 'blueprint') {
  wire = true; sat = 72; hueBase = 190; bgT = [214,76,9]; bgB = [210,64,18]; pegC = [192,78,62];
} else { // neon (default) — colorful column-hued beans
  sat = 85; hueBase = wrap(P.hue + secHue);
  bgT = [wrap(P.hue + secHue + 205), 58, 6]; bgB = [wrap(P.hue + secHue + 245), 46, 15]; pegC = [wrap(P.hue + secHue), 42, 32];
}

// --- emission ---
const inten = 0.5 + K.intensity * 0.6 + A.bass * 0.5;
let rate = (3 + P.density * 46) * inten * (0.5 + P.speed * 0.6);
if (S.drain) rate *= 0.12;
const maxBalls = 40 + Math.floor(P.density * 150);
S.emitAcc += rate * dt;
let guard = 0;
while (S.emitAcc >= 1 && S.balls.length < maxBalls && guard++ < 30) {
  S.emitAcc -= 1;
  const jit = (fr(S.nextId * 7.3) - 0.5) * binW * 0.35;
  S.balls.push({ id: S.nextId++, x: cx + jit, y: yTop, off: 0, row: 0, vy: 18 + fr(S.nextId * 3.1) * 34 });
}

// --- physics: fall + peg deflection + accrete into bins ---
const grav = (yPegBot - yTop) * 1.7;
const spd = P.speed * (0.7 + K.intensity * 0.4);
const alive = [];
for (const b of S.balls) {
  b.vy += grav * dt * spd;
  b.y += b.vy * dt * spd;
  while (b.row < R && b.y >= yTop + (b.row + 0.5) * rowH) {
    const dir = fr(b.id * 131.7 + b.row * 57.3 + 0.5) < 0.5 ? -1 : 1;
    b.off += dir * 0.5; b.row++;
  }
  const tx = cx + b.off * binW;
  b.x += (tx - b.x) * Math.min(1, dt * 15 * spd + 0.04);
  if (b.y >= yPegBot) {
    let bin = Math.round(b.off + R / 2); bin = Math.max(0, Math.min(R, bin));
    S.bins[bin] += 1;
    continue;
  }
  alive.push(b);
}
S.balls = alive;

// --- drain / refill cycle (smooth, non-strobe) ---
let maxc = 0; for (let i = 0; i < NB; i++) if (S.bins[i] > maxc) maxc = S.bins[i];
if (!S.drain && maxc >= capCount) S.drain = true;
if (S.drain) {
  const k = Math.pow(0.4, dt);
  for (let i = 0; i < NB; i++) S.bins[i] *= k;
  if (maxc * k < capCount * 0.03) S.drain = false;
}

// ================= RENDER =================
push();

// background ground tone (opaque fill for genart; skipped when compositing translucent)
if (P.alpha >= 100) {
  noStroke();
  const bands = 44, drift = 2 + K.swell * 3;
  for (let i = 0; i < bands; i++) {
    const f = i / (bands - 1);
    const h = wrap(bgT[0] + (bgB[0] - bgT[0]) * f);
    const s = bgT[1] + (bgB[1] - bgT[1]) * f;
    const br = bgT[2] + (bgB[2] - bgT[2] + drift * f) * f;
    fill(h, s, br);
    rect(0, i * (H / bands) - 0.5, W, H / bands + 1.5);
  }
}

// faint peg lattice
if (wire) {
  stroke(pegC[0], pegC[1], pegC[2], 30 * aMul); strokeWeight(1);
  const pr = Math.max(2, binW * 0.14);
  for (let r = 0; r < R; r++) for (let k = 0; k <= r; k++) {
    const px = cx + (k - r / 2) * binW, py = yTop + (r + 0.5) * rowH;
    line(px - pr, py, px + pr, py); line(px, py - pr, px, py + pr);
  }
} else {
  noStroke(); fill(pegC[0], pegC[1], pegC[2], 20 * aMul);
  const pr = Math.max(1.5, binW * 0.12);
  for (let r = 0; r < R; r++) for (let k = 0; k <= r; k++) {
    const px = cx + (k - r / 2) * binW, py = yTop + (r + 0.5) * rowH;
    ellipse(px, py, pr * 2, pr * 2);
  }
}

// histogram bars (lit by count)
const spark = A.treble * 0.6 + K.pulse * 0.25;
for (let bIdx = 0; bIdx < NB; bIdx++) {
  const frac = Math.max(0, Math.min(1, S.bins[bIdx] / capCount));
  if (frac < 0.004) continue;
  const barH = frac * (yBot - yPegBot);
  const bx = cx + (bIdx - R / 2) * binW;
  const bw = binW * 0.86;
  const ytopB = yBot - barH;
  let bh, bs, bb;
  if (thermal) { bh = wrap(240 - frac * 240); bs = 92 - frac * 34; bb = 40 + frac * 55; }
  else if (mono) { bh = hueBase; bs = sat; bb = 28 + frac * 62; }
  else if (wire) { bh = wrap(hueBase + ((bIdx / (NB - 1)) - 0.5) * 2 * hueSpread); bs = sat; bb = 55; }
  else { bh = wrap(hueBase + ((bIdx / (NB - 1)) - 0.5) * 2 * hueSpread); bs = sat; bb = 34 + frac * 60; }
  const bexp = Math.min(100, bb + P.energy * 22 + A.rms * 30);
  if (wire) {
    noFill(); stroke(bh, bs, bexp, 80 * aMul); strokeWeight(Math.max(1, binW * 0.05));
    rect(bx - bw / 2, ytopB, bw, barH);
    line(bx - bw / 2, yBot, bx + bw / 2, ytopB);
  } else {
    noStroke();
    fill(bh, bs, bexp * 0.75, 92 * aMul);
    rect(bx - bw / 2, ytopB, bw, barH);
    // lit cap glow
    push(); blendMode(ADD);
    fill(bh, Math.max(0, bs - 25), Math.min(100, bexp + 15), (30 + spark * 40) * aMul);
    rect(bx - bw / 2, ytopB - binW * 0.12, bw, binW * 0.3);
    pop();
  }
}

// falling balls
const bri = Math.min(100, 72 + P.energy * 28);
if (wire) {
  noFill(); strokeWeight(Math.max(1, binW * 0.06));
  const bR = Math.max(2, binW * 0.3);
  for (const b of S.balls) {
    stroke(hueBase, sat, 95, 82 * aMul);
    ellipse(b.x, b.y, bR * 2, bR * 2);
  }
} else {
  blendMode(ADD); noStroke();
  const bR = Math.max(2, binW * 0.32);
  const glowA = (10 + P.energy * 14 + A.bass * 12) * aMul;
  const coreA = (52 + A.rms * 30) * aMul;
  for (const b of S.balls) {
    const on = b.off / (R / 2);
    let hb, sb;
    if (thermal) { hb = wrap(50 - Math.abs(on) * 32); sb = 72; }
    else if (mono) { hb = hueBase; sb = sat; }
    else { hb = wrap(hueBase + on * hueSpread); sb = sat; }
    fill(hb, Math.max(0, sb - 30), bri, glowA);
    ellipse(b.x, b.y, bR * 2.7, bR * 2.7);
    fill(hb, sb, bri, coreA);
    ellipse(b.x, b.y, bR * 1.15, bR * 1.15);
  }
  blendMode(BLEND);
}

pop();
blendMode(BLEND);
